import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { RelayEntry, RelayRole, RelayView } from '../types'
import {
  cardFrom,
  DELIVERY_ASK,
  deliveryOf,
  isApproval,
  looksLikeRelay,
  pickPeers,
  prFromText,
  prRepoFrom,
  relayMessage,
  relaySender,
  repoFrom,
  roleFromPrompt,
  roleName,
  UNVERIFIED_RELAY,
  VERDICT_ASK,
} from './lib'

type $ = EngineInterface

const EMPTY: RelayView = { role: null, card: null, pr: null, rounds: 0, phase: '' }
const view = atom({ plugin: 'pr-relay', key: 'view' } as const, EMPTY)
const isPaused = atom({ plugin: 'pr-relay', key: 'isPaused' } as const, false)
const lastAnswer = atom({ plugin: 'pr-relay', key: 'lastAnswer' } as const, '')
// A sessão implementadora aberta neste worktree, enquanto esta não tem papel: vira o botão "Revisar".
const offer = atom({ plugin: 'pr-relay', key: 'offer' } as const, null)
const isOfferDismissed = atom({ plugin: 'pr-relay', key: 'isOfferDismissed' } as const, false)
// O papel veio de botão ou comando: o próximo prompt leva o resumo do par e o pedido de veredito.
const needsBrief = atom({ plugin: 'pr-relay', key: 'needsBrief' } as const, false)

const OFFER_POLL_MS = 3000

// Houve entrega (push/PR de um lado, review publicado do outro) no turno corrente.
let hasDeliveredThisTurn = false

async function registryDir($: $): Promise<string> {
  // No Windows nativo não há HOME; USERPROFILE é a pasta do usuário.
  const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE')) ?? '/tmp'

  return `${home.replace(/\\/g, '/')}/.local/state/claude-mods/pr-relay`
}

async function readEntry($: $, path: string): Promise<RelayEntry | undefined> {
  return $.fs
    .read(path)
    .then(text => JSON.parse(String(text)) as RelayEntry)
    .catch(() => undefined)
}

async function readEntries($: $): Promise<RelayEntry[]> {
  const dir = await registryDir($)
  const files = await $.fs.list(dir).catch(() => [])
  const entries = await Promise.all(
    files.filter(file => file.name.endsWith('.json')).map(file => readEntry($, `${dir}/${file.name}`)),
  )

  return entries.filter((entry): entry is RelayEntry => entry !== undefined)
}

/** O repositório desta sessão: o remoto origin da pasta ou, sem ele, o do link do PR. */
async function currentRepo($: $): Promise<string | null> {
  const repo = await $.session.repo().catch(() => null)

  return repoFrom(repo?.remote) ?? (await read($, view)).repo ?? null
}

/** Grava (ou renova) o registro desta sessão; `lastReport` só muda quando dado. */
async function saveEntry($: $, lastReport?: string, updatedAt?: number): Promise<RelayEntry | undefined> {
  const v = await read($, view)
  if (v.role === null) return undefined
  const sessionId = await $.session.id()
  const path = `${await registryDir($)}/${sessionId}.json`
  const previous = await readEntry($, path)
  const entry: RelayEntry = {
    sessionId,
    cwd: await $.session.cwd(),
    repo: await currentRepo($),
    role: v.role,
    card: v.card,
    pr: v.pr,
    lastReport: lastReport ?? previous?.lastReport ?? null,
    updatedAt: updatedAt ?? (await $.clock.now()),
  }
  await $.fs.write(path, JSON.stringify(entry, null, 2))

  return entry
}

async function peersOf($: $): Promise<RelayEntry[]> {
  const me = await saveEntry($)
  if (me === undefined) return []

  return pickPeers(await readEntries($), me, await $.clock.now())
}

/** Manda o relatório à sessão par aberta mais provável; diz para quem foi, ou por que não foi. */
async function relay($: $, answer: string): Promise<string> {
  const v = await read($, view)
  if (v.role === null) return 'esta sessão ainda não tem papel (use /relay dev ou /relay rev)'
  const other = v.role === 'implementer' ? 'reviewer' : 'implementer'
  const round = v.rounds + 1
  const text = relayMessage(v.role, answer, v.card, v.pr, round, await $.session.id())

  for (const peer of await peersOf($)) {
    const sent = await $.session.send({ to: { sessionId: peer.sessionId }, text })
    if (sent.isDelivered) {
      await update($, view, x => ({ ...x, rounds: round, phase: `enviado à sessão ${roleName(other)} (rodada ${round})` }))
      $.ui.toast(`⇄ Relatório enviado à sessão ${roleName(other)} (rodada ${round})`)
      return `enviado à sessão ${roleName(other)} ${peer.sessionId.slice(0, 8)}`
    }
  }

  const reason =
    v.role === 'implementer'
      ? 'ainda não há sessão revisora aberta: o relatório vai junto quando a revisão começar'
      : 'a sessão implementadora deste card não está aberta'
  await update($, view, x => ({ ...x, phase: `relatório guardado: ${reason}` }))
  $.ui.toast(`pr-relay: ${reason}`, { timeoutMs: 8000 })

  return reason
}

async function statusText($: $, maxRounds: number): Promise<string> {
  const v = await read($, view)
  if (v.role === null) return 'pr-relay: esta sessão não tem papel. Ele vem do /implement ou do prompt de code review com o link do PR; ou use /relay dev | rev.'
  const peers = await peersOf($)
  const paused = (await read($, isPaused)) ? ' · pausado' : ''

  return [
    `pr-relay: sessão ${roleName(v.role)} · ${v.card ?? 'sem card'} · ${v.pr === null ? 'sem PR' : `PR #${v.pr}`} · rodada ${v.rounds}/${maxRounds}${paused}`,
    v.phase === '' ? '' : `estado: ${v.phase}`,
    peers.length === 0 ? 'nenhuma sessão par encontrada' : `sessão par: ${peers.map(peer => peer.sessionId.slice(0, 8)).join(', ')}`,
  ]
    .filter(Boolean)
    .join('\n')
}

async function setRole($: $, role: RelayRole, text: string, peer?: RelayEntry): Promise<void> {
  const cwd = await $.session.cwd()
  await update($, view, v => ({
    ...v,
    role,
    repo: prRepoFrom(text) ?? v.repo ?? peer?.repo ?? null,
    card: cardFrom(text, cwd) ?? v.card ?? peer?.card ?? null,
    pr: prFromText(text) ?? v.pr ?? peer?.pr ?? null,
    phase: role === 'reviewer' ? 'revisando' : 'implementando',
  }))
  await update($, offer, () => null)
  await saveEntry($)
}

/**
 * A sessão par que mandou este relatório: chegou como mensagem de outra sessão,
 * o cabeçalho a nomeia, e ela está no registro como par desta (mesmo repositório,
 * PR e card). Sem papel ainda, esta sessão conta como o papel oposto ao dela.
 */
async function verifiedSender($: $, e: { origin: { kind: string }; text: string }): Promise<RelayEntry | undefined> {
  const claimed = relaySender(e.text)
  if (e.origin.kind !== 'peer' || claimed === undefined) return undefined
  const v = await read($, view)
  const now = await $.clock.now()
  const me: RelayEntry = {
    sessionId: await $.session.id(),
    cwd: await $.session.cwd(),
    repo: await currentRepo($),
    role: v.role ?? (claimed.from === 'reviewer' ? 'implementer' : 'reviewer'),
    card: v.card,
    pr: v.pr,
    lastReport: null,
    updatedAt: now,
  }
  const peer = pickPeers(await readEntries($), me, now).find(entry => entry.sessionId === claimed.sessionId)

  return peer?.role === claimed.from ? peer : undefined
}

/** A sessão implementadora aberta neste mesmo worktree, se houver. */
async function implementerHere($: $): Promise<RelayEntry | null> {
  const now = await $.clock.now()
  const me: RelayEntry = {
    sessionId: await $.session.id(),
    cwd: await $.session.cwd(),
    repo: await currentRepo($),
    role: 'reviewer',
    card: null,
    pr: null,
    lastReport: null,
    updatedAt: now,
  }

  return pickPeers(await readEntries($), me, now).find(peer => peer.cwd === me.cwd) ?? null
}

async function refreshOffer($: $): Promise<void> {
  if ((await read($, view)).role !== null || (await read($, isOfferDismissed))) return
  const found = await implementerHere($)
  const current = await read($, offer)
  if (found?.sessionId === current?.sessionId && found?.card === current?.card) return
  await update($, offer, () => found)
}

const HELP = [
  'pr-relay: leva o relatório entre a sessão implementadora e a revisora do mesmo PR.',
  '',
  '  /relay          o mesmo que /relay status',
  '  /relay status   papel desta sessão, card, PR, rodada e a sessão par encontrada',
  '  /relay dev      define esta sessão como implementadora',
  '  /relay rev      define esta sessão como revisora',
  '  /relay send     manda agora a última resposta desta sessão à sessão par',
  '  /relay off      pausa os envios automáticos (os relatórios ficam guardados)',
  '  /relay on       retoma os envios automáticos',
  '  /relay reset    zera o contador de rodadas',
  '  /relay help     mostra esta ajuda',
].join('\n')

export const register: Register = (on, options) => {
  const maxRounds = Number(options.maxRounds ?? 4) || 4

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'relay',
      description: 'pr-relay: estado, pausar/retomar, mandar a última resposta à sessão par, definir o papel',
      argumentHint: '[status|dev|rev|send|on|off|reset|help]',
    })
    if (e.isInteractive) {
      await refreshOffer($).catch(() => undefined)
      $.clock.every(OFFER_POLL_MS, () => refreshOffer($).catch(() => undefined))
    }

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    // Sem delete no $.fs: um registro com data zero sai de toda busca por pares.
    await saveEntry($, undefined, 0).catch(() => undefined)

    return next(e)
  })

  // O papel vem do primeiro prompt; o revisor recebe junto o último resumo do implementador.
  on('prompt.submit', async ($, e, next) => {
    if (e.text.startsWith('[pr-relay]')) return next(e)
    const role = roleFromPrompt(e.text)
    if (role !== undefined) await setRole($, role, e.text)
    // Why: a cada prompt, e não só no primeiro, para a ordem sobreviver à compactação e a pedidos seguintes.
    if ((await read($, view)).role === 'implementer') {
      await update($, needsBrief, () => false)

      return next({ ...e, context: [...(e.context ?? []), DELIVERY_ASK] })
    }
    const isBriefDue = await read($, needsBrief)
    if (role === undefined && !isBriefDue) return next(e)
    await update($, needsBrief, () => false)
    if ((await read($, view)).role !== 'reviewer') return next(e)
    const report = (await peersOf($)).find(peer => peer.lastReport !== null)?.lastReport
    const isNew = report != null && !e.text.includes(report.slice(0, 120))
    const summary = isNew ? [`Resumo da entrega escrito pela sessão implementadora (via pr-relay):\n\n${report}`] : []

    return next({ ...e, context: [...(e.context ?? []), ...summary, VERDICT_ASK] })
  })

  // Só um par registrado, deste repositório e PR, fala pelo relay; o resto é texto de terceiros.
  on('session.receive', async ($, e, next) => {
    if (!looksLikeRelay(e.text)) return next(e)
    const sender = await verifiedSender($, e)
    if (sender === undefined) return next({ ...e, text: `${UNVERIFIED_RELAY}\n\n${e.text}` })
    if ((await read($, view)).role === null) await setRole($, sender.role === 'reviewer' ? 'implementer' : 'reviewer', '', sender)
    await update($, view, x => ({ ...x, phase: `recebeu o relatório da sessão ${roleName(sender.role)}` }))

    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    hasDeliveredThisTurn = false

    return next(e)
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    const v = await read($, view)
    if (v.role === null || ran.deny !== undefined || ran.isError === true || !deliveryOf(e.command, v.role)) return ran
    hasDeliveredThisTurn = true
    const pr = prFromText(ran.text ?? '') ?? prFromText(e.command)
    if (pr !== null && v.pr === null) await update($, view, x => ({ ...x, pr }))

    return ran
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined || e.reason !== 'answer' || e.answer.trim() === '') return result
    await update($, lastAnswer, () => e.answer)
    const v = await read($, view)
    if (v.role === null || !hasDeliveredThisTurn) return result
    hasDeliveredThisTurn = false
    await saveEntry($, e.answer)

    if (v.role === 'reviewer' && isApproval(e.answer)) {
      await update($, view, x => ({ ...x, phase: 'revisor sem bloqueios: pronto para merge' }))
      $.ui.toast(`✅ ${v.pr === null ? 'PR' : `PR #${v.pr}`}: o revisor não vê bloqueio. O merge é com você (/relay send leva os nits ao implementador).`, { timeoutMs: 15_000 })
      return result
    }
    if (await read($, isPaused)) {
      await update($, view, x => ({ ...x, phase: 'pausado: relatório guardado (/relay send envia)' }))
      return result
    }
    if (v.rounds >= maxRounds) {
      await update($, view, x => ({ ...x, phase: `limite de ${maxRounds} rodadas: a decisão volta para você` }))
      $.ui.toast(`pr-relay: ${maxRounds} rodadas sem convergir. Veja o PR; /relay send continua, /relay reset zera.`, { timeoutMs: 15_000 })
      return result
    }
    await relay($, e.answer)

    return result
  })

  on('command.run', { command: 'relay' }, async ($, e) => {
    const [action = 'status'] = e.args.trim().split(/\s+/).filter(Boolean)
    if (action === 'off') {
      await update($, isPaused, () => true)
      return { text: 'pr-relay pausado: os relatórios ficam guardados até /relay on ou /relay send.' }
    }
    if (action === 'on') {
      await update($, isPaused, () => false)
      return { text: 'pr-relay ligado.' }
    }
    if (action === 'reset') {
      await update($, view, v => ({ ...v, rounds: 0, phase: '' }))
      return { text: 'Rodadas zeradas.' }
    }
    if (action === 'dev' || action === 'rev') {
      const role = action === 'dev' ? 'implementer' : 'reviewer'
      await setRole($, role, '')
      await update($, needsBrief, () => role === 'reviewer')
      return { text: `Esta sessão agora é a ${roleName(role)}.` }
    }
    if (action === 'help') return { text: HELP }
    if (action === 'send') {
      const answer = await read($, lastAnswer)
      if (answer === '') return { text: 'Ainda não há resposta nesta sessão para enviar.' }
      return { text: `pr-relay: ${await relay($, answer)}` }
    }

    if (action !== 'status') return { text: `Comando desconhecido: /relay ${action}\n\n${HELP}` }

    return { text: await statusText($, maxRounds) }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const v = await read($, view)
    if (e.props.hasSurvey) return next(e)
    if (v.role === null) {
      const peer = await read($, offer)
      if (peer === null || e.props.view.agentId || (await read($, isOfferDismissed))) return next(e)
      const { Box, Button, Text } = $.ui.resolve(e)
      const where = [peer.card, peer.pr === null ? null : `PR #${peer.pr}`].filter(Boolean).join(' · ')
      const review = async () => {
        await setRole($, 'reviewer', '', peer)
        await update($, needsBrief, () => true)
        $.ui.toast('⇄ pr-relay: esta sessão agora é a revisora')
      }

      return (
        <Box flexDirection="row" gap={1}>
          <Text dimColor>
            ⇄ pr-relay · sessão implementadora aberta neste worktree{where === '' ? '' : ` · ${where}`}
          </Text>
          <Button key="review" label="Revisar" variant="primary" hotkey="r" onPress={review} />
          <Button key="dismiss-offer" label="Dispensar" role="dismiss" onPress={() => update($, isOfferDismissed, () => true)} />
        </Box>
      )
    }
    const paused = await read($, isPaused)
    const { Box, Button, Text } = $.ui.resolve(e)
    const where = [v.card, v.pr === null ? null : `PR #${v.pr}`].filter(Boolean).join(' · ')

    return (
      <Box gap={1}>
        <Text dimColor>
          ⇄ pr-relay · {roleName(v.role)}
          {where === '' ? '' : ` · ${where}`} · rodada {v.rounds}/{maxRounds}
          {v.phase === '' ? '' : ` · ${v.phase}`}
        </Text>
        <Button key="pause" label={paused ? 'Retomar' : 'Pausar'} plain onPress={() => update($, isPaused, x => !x)} />
      </Box>
    )
  })
}

