export type RelayRole = 'implementer' | 'reviewer'

/** O que cada sessão grava no registro compartilhado (um arquivo por sessão). */
export type RelayEntry = {
  sessionId: string
  cwd: string
  /** O repositório como `host/dono/nome` (do remoto origin ou do link do PR); null se não se sabe. */
  repo?: string | null
  role: RelayRole
  card: string | null
  pr: number | null
  lastReport: string | null
  updatedAt: number
}

export type RelayView = {
  role: RelayRole | null
  /** O repositório do link do PR, para quando a pasta da sessão não diz. */
  repo?: string | null
  card: string | null
  pr: number | null
  rounds: number
  phase: string
}

declare module 'claude-code' {
  interface PluginState {
    'pr-relay': {
      view: RelayView
      isPaused: boolean
      lastAnswer: string
      offer: RelayEntry | null
      isOfferDismissed: boolean
      needsBrief: boolean
    }
  }
}
